INSERT INTO CMP_COMP_EMPLE_INFO_TBL (
	COMP_SEQ
  , EMPLE_TP	
  , EMPLE_STAT_TP
  , EMPLE_DGR_TP
  , USE_YN
  , EMPLE_NM
  , EMPLE_LOGN_ID
  , EMPLE_LOGN_PWD
  , EMPLE_DEPT_NM
  , EMPLE_PSTN_NM
  , EMPLE_MBL_NO
  , ADTN_DESC
  , RGST_DT
  , RGST_SEQ
)
VALUES (
	#{compSeq, jdbcType=NUMERIC}
  , 	#{empleTp, jdbcType=VARCHAR}
  , 	#{empleStatTp, jdbcType=VARCHAR}
  , 	#{empleDgrTp, jdbcType=VARCHAR}
  , 	#{useYn, jdbcType=VARCHAR}
  , 	#{empleNm, jdbcType=VARCHAR}
  , 	#{empleLognId, jdbcType=VARCHAR}
  , 	#{empleLognPwd, jdbcType=VARCHAR}
  , 	#{empleDeptNm, jdbcType=VARCHAR}
  , 	#{emplePstnNm, jdbcType=VARCHAR}
  , 	#{empleMblNo, jdbcType=VARCHAR}
  , 	#{adtnDesc, jdbcType=VARCHAR}
  , CURRENT_TIMESTAMP(3)
  , #{rgstSeq, jdbcType=NUMERIC}
)

