UPDATE CMP_COMP_EMPLE_INFO_TBL
SET 		EMPLE_TP = (
				CASE
					WHEN (#{empleTp, jdbcType=VARCHAR} IS NULL OR #{empleTp, jdbcType=VARCHAR} = '') THEN EMPLE_TP
					ELSE #{empleTp, jdbcType=VARCHAR}
				END
			)
		  , EMPLE_STAT_TP = (
				CASE
					WHEN (#{empleStatTp, jdbcType=VARCHAR} IS NULL OR #{empleStatTp, jdbcType=VARCHAR} = '') THEN EMPLE_STAT_TP
					ELSE #{empleStatTp, jdbcType=VARCHAR}
				END
		  	)
		  , EMPLE_DGR_TP = (
				CASE
					WHEN (#{empleDgrTp, jdbcType=VARCHAR} IS NULL OR #{empleDgrTp, jdbcType=VARCHAR} = '') THEN EMPLE_DGR_TP
					ELSE #{empleDgrTp, jdbcType=VARCHAR}
				END
		  	)
		  , USE_YN = (
				CASE
					WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN USE_YN
					ELSE #{useYn, jdbcType=VARCHAR}
				END
		  	)
		  , EMPLE_NM = (
				CASE
					WHEN (#{empleNm, jdbcType=VARCHAR} IS NULL OR #{empleNm, jdbcType=VARCHAR} = '') THEN EMPLE_NM
					ELSE #{empleNm, jdbcType=VARCHAR}
				END
		  	)
		  , EMPLE_DEPT_NM = (
				CASE
					WHEN (#{empleDeptNm, jdbcType=VARCHAR} IS NULL OR #{empleDeptNm, jdbcType=VARCHAR} = '') THEN EMPLE_DEPT_NM
					ELSE #{empleDeptNm, jdbcType=VARCHAR}
				END
		  	)
		  , EMPLE_PSTN_NM = (
				CASE
					WHEN (#{emplePstnNm, jdbcType=VARCHAR} IS NULL OR #{emplePstnNm, jdbcType=VARCHAR} = '') THEN EMPLE_PSTN_NM
					ELSE #{emplePstnNm, jdbcType=VARCHAR}
				END	
		  	)
		  , EMPLE_MBL_NO = (
				CASE
					WHEN (#{empleMblNo, jdbcType=VARCHAR} IS NULL OR #{empleMblNo, jdbcType=VARCHAR} = '') THEN EMPLE_MBL_NO
					ELSE #{empleMblNo, jdbcType=VARCHAR}
				END	
		  	)
		  , ADTN_DESC = (
				CASE
					WHEN (#{adtnDesc, jdbcType=VARCHAR} IS NULL OR #{adtnDesc, jdbcType=VARCHAR} = '') THEN ADTN_DESC
					ELSE #{adtnDesc, jdbcType=VARCHAR}
				END
		  	)
		  , UPDT_DT = CURRENT_TIMESTAMP(3)
		  , UPDT_SEQ = #{updtSeq, jdbcType=NUMERIC}
WHERE 	1	=	1
AND 		DELT_YN 	= 	'N'
AND 		COMP_SEQ = #{compSeq, jdbcType=NUMERIC}
AND 		EMPLE_SEQ = #{empleSeq, jdbcType=NUMERIC}

